package com.sobrenaturaldirector.decision.trace;
import java.util.*; import com.sobrenaturaldirector.decision.model.Intent;
public final class DecisionTrace { private final long tick, rngSeed; private final String contextFingerprint; private final List<CandidateTrace> candidates; private final Intent selected; private final String selectedId; public DecisionTrace(long tick,long rngSeed,String fingerprint,List<CandidateTrace> candidates,Intent selected,String selectedId){this.tick=tick;this.rngSeed=rngSeed;this.contextFingerprint=fingerprint;this.candidates=Collections.unmodifiableList(new ArrayList<CandidateTrace>(candidates));this.selected=selected;this.selectedId=selectedId;} public long getTick(){return tick;} public long getRngSeed(){return rngSeed;} public String getContextFingerprint(){return contextFingerprint;} public List<CandidateTrace> getCandidates(){return candidates;} public Intent getSelected(){return selected;} public String getSelectedId(){return selectedId;} }
